{
  "apiVersion": "edge.forms.takoform.com",
  "kind": "VectorIndex",
  "definitionVersion": "0.1.0-dev.1",
  "title": "Install-owned vector index",
  "description": "Unpublished install-owned vector index candidate. The resource fixes a positive vector dimension, cosine metric, and bounded optional metadata filter-key set. Native storage, endpoints, credentials, table names, and provider IDs are Host-private. Lifecycle is create, read, delete, and observe only; configuration is immutable and no import or update capability is claimed by this candidate. Deleting a bound Resource is refused. A successful unbound delete reports application-visible absence; physical media retention or purge is operator policy, not a portable promise. Observed state reports dimension, metric, filterKeys, and an eventual total vector count across all namespaces; status outputs are not claimed.",
  "role": "identity",
  "requiresHostApi": "forms.takoform.com/v1",
  "desiredSchema": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "additionalProperties": false,
    "description": "Unpublished install-owned vector index candidate. The resource fixes a positive vector dimension, cosine metric, and bounded optional metadata filter-key set. Native storage, endpoints, credentials, table names, and provider IDs are Host-private. Lifecycle is create, read, delete, and observe only; configuration is immutable and no import or update capability is claimed by this candidate. Deleting a bound Resource is refused. A successful unbound delete reports application-visible absence; physical media retention or purge is operator policy, not a portable promise. Observed state reports dimension, metric, filterKeys, and an eventual total vector count across all namespaces; status outputs are not claimed.",
    "properties": {
      "dimension": {
        "description": "Required positive vector length. Every stored and query vector must have exactly this many components; each component is converted to IEEE 754 binary32 before storage and a host rejects wrong length rather than padding or truncating it.",
        "maximum": 1536,
        "minimum": 1,
        "type": "integer"
      },
      "filterKeys": {
        "default": [],
        "description": "Optional immutable set of metadata keys callers may use in exact, type-sensitive equality filters. Omission means an empty set; a filter key not declared here is rejected. Observed keys use lexical ordering matching canonical set defaults. Keys are simple ASCII identifiers and at most eight may be declared.",
        "items": {
          "pattern": "^[A-Za-z][A-Za-z0-9_]{0,63}$",
          "type": "string"
        },
        "maxItems": 8,
        "type": "array",
        "uniqueItems": true
      },
      "metric": {
        "description": "Required immutable similarity metric. This candidate supports cosine similarity only; scores are higher-is-better and a host rejects another metric instead of silently substituting one.",
        "enum": [
          "cosine"
        ],
        "type": "string"
      }
    },
    "required": [
      "dimension",
      "metric"
    ],
    "title": "Install-owned vector index desired state",
    "type": "object"
  },
