      "count": {
        "description": "Eventual total number of records across all namespaces; it may lag a completed mutation.",
        "minimum": 0,
        "type": "integer"
      },
      "dimension": {
        "maximum": 1536,
        "minimum": 1,
        "type": "integer"
      },
      "filterKeys": {
        "description": "Declared filter keys are emitted in lexical order, matching canonical set-default ordering.",
        "items": {
          "pattern": "^[A-Za-z][A-Za-z0-9_]{0,63}$",
          "type": "string"
        },
        "maxItems": 8,
        "type": "array",
        "uniqueItems": true
      },
      "metric": {
        "enum": [
          "cosine"
        ],
        "type": "string"
      }
    },
    "required": [
      "count",
      "dimension",
      "filterKeys",
      "metric"
    ],
    "type": "object"
  },
  "immutableFields": [
    "/dimension",
    "/filterKeys",
    "/metric"
  ],
  "lifecycleCapabilities": [
    "create",
    "read",
    "delete",
    "observe"
  ],
  "providedInterfaces": [
    {
      "apiVersion": "interfaces.takoform.com/v1alpha1",
      "name": "edge.vector",
      "version": "0.1.0",
      "schemaDigest": "sha256:6df8b7680b0ff278cb8fcb6f56c602ec5d6bb9b4ec115a6172e70e6b54d6cada"
    }
  ],
  "conformanceFixtures": [
