}

binding.definitionJson:
{
  "apiVersion": "bindings.takoform.com/v1alpha2",
  "kind": "BindingDefinition",
  "name": "module-worker.edge-vector",
  "version": "1.0.0",
  "title": "Module Worker vector index binding",
  "description": "Projects the exact edge.vector@0.1.0 Interface into an ES Module Worker under one JavaScript binding name. The runtime surface is env.NAME with exactly these methods: env.NAME.upsert(input), env.NAME.get(input), env.NAME.delete(input), and env.NAME.query(input). Each method takes EXACTLY one argument: one closed JSON-object input matching the corresponding Interface operation schema. Extra positional arguments, missing arguments, unknown object members, and inputs that do not match the operation schema are rejected before dispatch with Error.name=invalid_spec. Resource-dependent constraints, such as the configured index dimension and filter keys, are validated by the target Interface before effects and reject with the same error name. Every method returns a Promise that resolves to the exact Interface output document: get resolves to {vectors}, upsert and delete resolve to {ids,count}, and query resolves to {matches,count}; no wrapper or provider-specific result is added. Other failures reject with an Error whose name is the exact corresponding edge.vector Interface error code (invalid_spec, quota, or unavailable); transport unavailable is named unavailable. The binding exposes no vendor or native methods, native IDs, endpoints, credentials, or backend metadata.",
  "sourceRole": "revision",
  "targetInterface": {
    "apiVersion": "interfaces.takoform.com/v1alpha1",
    "name": "edge.vector",
    "version": "0.1.0",
    "schemaDigest": "sha256:6df8b7680b0ff278cb8fcb6f56c602ec5d6bb9b4ec115a6172e70e6b54d6cada"
  },
  "allowedTargetForms": [
    {
      "apiVersion": "edge.forms.takoform.com",
      "kind": "VectorIndex"
    }
  ],
  "bindingNameGrammar": "^[A-Za-z_$][A-Za-z0-9_$]*$",
  "runtimeProjection": {
    "operations": [
      "upsert",
      "get",
      "delete",
      "query"
    ]
  },
  "lifecycle": {
    "targetDeletion": "refuse_while_bound"
  }
}
